return { PEN, sunVector, box, lift, castPoint, castOnPlane, clipRect, groundPoint, hatchSegments, unionOutline, penScene, figSketchVocabulary, figSketchRules, figSketchConvention, figSketchPlan, figSketchElevation, figSketchAxo, figSketchPerspective, figSketchTechnique, SKETCH_FIGURES };
