const { RAD, wrap, solarPosition, declination, equationOfTime, eotComponents, noonAltitude, calendarDate, dayOfYear, clockToSolar, shadowAngles, shadeWindow, deviceVSA, deviceHSA, overhangMaskAltitude, stereographic, faceMask, isMasked, sundialTip, shadowVector, shadowPolygon, massingStudy, formatHour } = modules[1];

const { svgDocument, view, f } = modules[3];

